{"implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    alloc = {}
    for s in segments:
        alloc[s['name']] = s['minimum']
        budget -= s['minimum']
    if budget < 0:
        budget = 0
    sorted_segs = sorted(segments, key=lambda x: -x['importance'])
    for s in sorted_segs:
        name = s['name']
        max_add = s['capacity'] - alloc[name]
        if max_add <= 0:
            continue
        add = min(budget, max_add)
        alloc[name] += add
        budget -= add
        if budget == 0:
            break
    total_importance = sum(s['importance'] * alloc[s['name']] for s in segments)
    return {'allocations': alloc, 'total_importance': total_importance}"}
